const meta = $('Pobierz dane Meta Ads').first().json.data?.[0] || {};
const rows = $('Pobierz dane Google Ads').first().json.results || [];
const g = rows.reduce((a, r) => ({
  koszt: a.koszt + Number(r.metrics?.costMicros || 0) / 1e6,
  klikniecia: a.klikniecia + Number(r.metrics?.clicks || 0),
  wyswietlenia: a.wyswietlenia + Number(r.metrics?.impressions || 0),
  konwersje: a.konwersje + Number(r.metrics?.conversions || 0),
}), { koszt: 0, klikniecia: 0, wyswietlenia: 0, konwersje: 0 });
const m = { koszt: Number(meta.spend || 0), klikniecia: Number(meta.clicks || 0), wyswietlenia: Number(meta.impressions || 0) };
const f = (n) => n.toLocaleString('pl-PL', { maximumFractionDigits: 2 });
const tabela = 'Meta: ' + f(m.koszt) + ' zł, ' + f(m.klikniecia) + ' klik., ' + f(m.wyswietlenia) + ' wyśw.\n' +
  'Google: ' + f(g.koszt) + ' zł, ' + f(g.klikniecia) + ' klik., ' + f(g.konwersje) + ' konw.';
return { json: { meta: m, google: g, tabela } };

const SYSTEM = "Jesteś analitykiem marketingu. Na podstawie liczb z ostatnich 7 dni napisz 2-3 zdania komentarza i maksymalnie 3 konkretne rekomendacje. Opieraj się wyłącznie na podanych liczbach.\n\nOdpowiedz WYŁĄCZNIE poprawnym obiektem JSON z polami: {\"komentarz\": tekst, \"rekomendacje\": tablica krótkich zdań}. Nie wymyślaj faktów, cen ani danych, których nie ma w treści.";
const user = `Wyniki z ostatnich 7 dni:\n${$json.tabela}`;
return {
  json: {
    ...$json,
    _aiRequest: {
      model: ($('Konfiguracja').first().json.modelAI || "gpt-4o-mini"),
      max_tokens: 600,
      temperature: 0.3,
      response_format: { type: 'json_object' },
      messages: [
        { role: 'system', content: SYSTEM },
        { role: 'user', content: String(user).slice(0, 12000) },
      ],
    },
  },
};

// Łączymy dane wejściowe (sprzed wywołania AI) z odpowiedzią modelu.
const ctx = { ...$('AI: prompt (komentarz do raportu)').item.json };
delete ctx._aiRequest;
let out = {};
let aiError = '';
try {
  const raw = $json.choices?.[0]?.message?.content ?? '';
  out = JSON.parse(raw);
  if (!out || typeof out !== 'object' || Array.isArray(out)) throw new Error('to nie obiekt');
} catch (e) {
  aiError = 'Nie udało się odczytać odpowiedzi AI: ' + e.message;
  out = {};
}
const defaults = {"komentarz":"","rekomendacje":""};
for (const [k, v] of Object.entries(defaults)) if (out[k] === undefined || out[k] === null) out[k] = v;
for (const [k, v] of Object.entries(out)) if (typeof v === 'string') out[k] = v.slice(0, 4000);

return { json: { ...ctx, ...out, _aiOk: !aiError, _aiError: aiError } };
